-- GENERADO por db/cargador/generar_comentarios_v22.py (diccionario del Interno + descripciones manuales).
-- Ciclo 3 -- Paso 2: COMMENT en toda tabla y campo de core. api.diccionario se lee de aqui.
-- Solo escribe donde el objeto existe y aun no tiene comentario.
do $c$
declare
  j jsonb := $j${"tablas": {"unidad_territorial": "Municipios (13) y localidades (2,772) de Campeche con su CVEGEO de INEGI y poblacion. Llave del territorio para mediciones, capas e instrumentos municipales.", "unidad_territorial_geom": "Poligono de cada unidad territorial (relacion 1 a 0..1). Se carga en el Ciclo 9 desde los GeoJSON oficiales.", "eje_tematico": "Los 5 ejes estrategicos de la EEMSV que clasifican a los indicadores.", "sector": "Sector tematico o administrativo de un indicador: definitivo (SD-xx) u original (SO-xx).", "fuente_informacion": "Fuente oficial del dato de un indicador (INEGI, ATUS, CONEVAL, SICT...).", "instrumento_origen": "Ley, plan o estrategia de donde nace un indicador: la EEMSV (estatal) y los PIMUS municipales.", "matriz_instrumento": "Renglon de la matriz de indicadores de un PIMUS: objetivo, meta e indicador tal como lo nombra el plan.", "indicador": "Ficha tecnica MIR-SMART de cada indicador del sistema. Solo los aprobados (que pasan la compuerta) admiten mediciones.", "indicador_eje": "Tabla puente indicador-eje: todos los ejes que atiende un indicador; el principal coincide con indicador.id_eje.", "indicador_instrumento": "Vinculo muchos-a-muchos entre indicadores e instrumentos: origen (nace en el instrumento), directa (mide lo mismo) o parcial.", "umbral_semaforo": "Umbrales del semaforo (verde, amarillo) versionados por vigencia; id_indicador nulo = umbral global.", "periodo": "Corte de tiempo de una medicion (anio y etiqueta). Los tipos y fechas los llena el equipo (OBS-21).", "medicion_indicador": "Valor medido de un indicador en una unidad territorial y un periodo, con su estado dentro del flujo captura-revision-validacion-publicacion y la firma de quien captura y quien valida.", "evidencia_medicion": "Medio de verificacion de una medicion: archivo con huella SHA-256. Se exige al menos uno para validar (R12).", "capa": "Capa tematica del visor: sus metadatos ISO, estatus de publicacion y vinculo con el instrumento de origen.", "capa_indicador": "Vinculo capa-indicador: que capas ayudan a leer cada indicador.", "capa_vector": "Elemento geografico individual de una capa (punto, linea o poligono) con sus atributos tematicos en `propiedades`. Se carga en el Ciclo 9.", "capa_version": "Historial de versiones de la ficha de metadatos de cada capa; la vigente es la mayor.", "bitacora_cambio": "Bitacora general de cambios del sistema. Solo insercion: no admite UPDATE, DELETE ni TRUNCATE. Equivale a la tabla `bitacora` del documento v2.2.", "dictamen": "Constancia de cada decision de revision (validar, rechazar, publicar) sobre una medicion, capa o indicador.", "hallazgo_auditoria": "Observacion del Auditor sobre una medicion, con severidad y seguimiento hasta su cierre.", "invitacion": "Invitacion de alta con token de un solo uso (solo su hash). Mecanismo latente: la decision vigente es el alta directa por el Administrador Titular.", "bitacora": "Bitacora de cuentas (Ciclo 1): altas, cambios de rol, de ambito, bajas y reactivaciones sobre core.perfil.", "perfil": "Cuenta de la plataforma: rol, ambito y dependencia de cada persona, ligada 1 a 1 con auth.users. Equivale a `usuario` + `perfil` del documento v2.2.", "schema_migraciones": "Control de migraciones aplicadas (nombre, sha256, origen y fecha). Lo mantiene scripts/migrar.sh."}, "campos": {"eje_tematico": {"id": "Identificador del eje.", "numero_eje": "Número oficial del eje (1 a 5).", "nombre": "Nombre oficial del eje.", "activo": "Baja lógica. Por omisión TRUE."}, "sector": {"id": "Clave del sector: SD-xx (definitivo) o SO-xx (original).", "nombre": "Nombre del sector.", "tipo": "original | definitivo.", "activo": "Baja lógica."}, "fuente_informacion": {"id": "Identificador de la fuente.", "nombre": "Nombre completo de la fuente.", "siglas": "Siglas. Vacío en la fuente 16.", "activo": "Baja lógica."}, "instrumento_origen": {"id": "ID corto: sigla + municipio + número (Eemsv01, PimusCal01). El número admite versiones futuras del mismo plan.", "uuid_legado": "UUID de la versión 1; permite cruzar con el respaldo de PostGIS.", "clave": "Clave institucional (EEMSV, PIMUS-CALKINI…).", "nombre": "Nombre oficial del instrumento.", "ambito": "Estatal | Municipal.", "id_unidad_ambito": "Municipio que cubre un instrumento municipal (→ unidad_territorial.id). Vacío si es estatal.", "competencia": "Quién es competente: Gobierno del Estado (EEMSV) o el municipio que emitió el PIMUS. Sustituye a fuente_informacion.competencia (OBS-12).", "vigencia_desde": "Inicio de vigencia. Pendiente de dato en los 6 registros.", "vigencia_hasta": "Fin de vigencia.", "activo": "Baja lógica."}, "indicador": {"id": "Clave en PascalCase sin guion (Im01, Ee05, Accgir01). Sustituye al UUID.", "uuid_legado": "UUID de la versión 1.", "id_eje": "→ eje_tematico.id.", "id_sector": "→ sector.id.", "id_fuente": "→ fuente_informacion.id.", "clave": "Clave del indicador (ACCGIR01, EE-xx, IM-xx…).", "nombre": "Nombre del indicador.", "variable": "Definición de la variable que se mide.", "meta": "Meta en texto libre (mezcla «Por definir» y metas numéricas).", "tendencia": "Ascendente | Descendente: sentido en que mejora el indicador. Llenado en 38 de los 40 IM-xx a partir de su meta y de su PIMUS.", "valor_meta": "Meta numérica, cuando exista. Hoy vacía: sin línea base no se puede fijar (OBS-13).", "linea_base": "Primer valor publicado que sirve de referencia para el semáforo.", "anio_linea_base": "Año de la línea base.", "nivel_mir": "Fin | Propósito | Componentes | Actividades.", "smart_medible": "Criterio SMART: medible.", "smart_alcanzable": "Criterio SMART: alcanzable. Estaba en el Mermaid pero no en la Tabla 1.", "smart_temporal": "Criterio SMART: temporal.", "estatus_aprobado": "TRUE cuando la ficha está aprobada.", "activo": "Baja lógica.", "created_at": "Alta del registro.", "updated_at": "Última modificación.", "responsable": "Responsable o competente del dato del indicador (D-03: pendiente de captura por indicador)."}, "periodo": {"id": "Identificador del periodo.", "anio": "Año del corte.", "etiqueta": "Etiqueta legible (p. ej. «2026-T1»).", "tipo_periodo": "anual | semestral | trimestral | mensual. Vacío para que el equipo lo llene (OBS-21).", "fecha_inicio": "Primer día del periodo. Vacío para que el equipo lo llene (OBS-21).", "fecha_fin": "Último día del periodo. Vacío para que el equipo lo llene (OBS-21)."}, "unidad_territorial": {"id": "CVEGEO INEGI: 5 dígitos (municipio) o 9 (localidad). Se conserva tal cual.", "id_padre": "→ unidad_territorial.id del municipio donde está la localidad. Vacío en municipios.", "nivel": "municipio | localidad.", "cve_ent": "Clave de entidad (04).", "nom_ent": "Nombre de la entidad.", "cve_mun": "Clave del municipio donde está hoy la unidad.", "nom_mun": "Nombre del municipio.", "cve_loc": "Clave de localidad; 0000 = total del municipio.", "nom_loc": "Nombre de la localidad. Estaba en el Mermaid pero no en la Tabla 3.", "pob_tot": "Población total (Censo 2020 o tabla del responsable).", "cvegeo": "Clave vigente según ubicación; difiere del id en 28 localidades reubicadas.", "activo": "Baja lógica."}, "unidad_territorial_geom": {"id_unidad": "→ unidad_territorial.id (relación 1 a 0..1).", "geom": "Geometría PostGIS. Fuera del Excel (carpeta geojson/04_unidad_territorial)."}, "medicion_indicador": {"id": "Identificador de la medición.", "id_indicador": "→ indicador.id.", "id_unidad": "→ unidad_territorial.id.", "id_periodo": "→ periodo.id.", "usuario_captura": "→ usuario.id de quien captura.", "usuario_validacion": "→ usuario.id de quien valida. Vacío mientras está en borrador.", "valor": "Valor cuantitativo.", "valor_texto": "Valor cualitativo.", "desagregaciones": "Desagregaciones (sexo, edad, modo…)", "estado": "borrador | revision | rechazado | vigente_admin | vigente_publico (OBS-28).", "fecha_captura": "Se renombra desde fecha_registro (Excel v1).", "fecha_validacion": "Fecha de validación.", "created_at": "Alta del registro.", "updated_at": "Última modificación."}, "capa": {"id": "Nomenclatura en PascalCase (eje como prefijo E) + número de 2 dígitos: Inf03, DIt01, E2Tpp05.", "uuid_legado": "UUID de la versión 1.", "titulo": "Título de la capa. Tren Maya y Red Federal indican su trazo (Mapa Base / Diagnóstico).", "proposito": "Propósito declarado en la ficha ISO.", "tipo_geometria": "Punto | Línea | Polígono.", "srid_origen": "EPSG de origen (6372, 4326, 32615, 6365).", "estatus": "vigente_publico | borrador.", "responsable": "Custodio de la capa.", "conjunto_datos": "Conjunto de datos de origen (DENUE, Red Nacional de Caminos…)", "id_instrumento": "→ instrumento_origen.id. Eemsv01 para capas de Diagnóstico y Estrategia; vacío en Mapa Base.", "archivo": "Nombre del archivo fuente (shapefile).", "grupos": "Grupo(s) del visor donde se publica.", "nomenclatura": "Código del grupo (INF, D-IT, 2TPP…)", "n_elementos": "Elementos cargados en capa_vector.", "geojson": "Ruta del GeoJSON entregado.", "activo": "Baja lógica.", "metadatos_extra": "Metadatos ISO de la capa en JSON: custodio, contacto, fuente, linaje, escala, sistema de coordenadas, fecha de corte, periodicidad, restriccion de uso. Para publicar se exigen custodio, fuente_origen, linaje y sistema_coordenadas.", "created_at": "Alta del registro.", "updated_at": "Ultima modificacion."}, "capa_vector": {"id": "Identificador del elemento.", "id_capa": "→ capa.id.", "id_unidad": "→ unidad_territorial.id donde cae el elemento (localidad si hay cve_loc; si no, municipio). Vacío fuera de Campeche.", "id_origen": "Identificador del elemento en el archivo fuente.", "cve_ent": "Claves geoestadísticas asignadas al elemento.", "cve_mun": "Claves geoestadísticas asignadas al elemento.", "cve_loc": "Claves geoestadísticas asignadas al elemento.", "nombre": "Atributos comunes de lectura y simbología.", "clasif": "Atributos comunes de lectura y simbología.", "fecha_dato": "Atributos comunes de lectura y simbología.", "metodo_cve_mun": "interseccion | proximidad<=1000m | proximidad_aguas_estatales | fuera_de_campeche.", "vig_desde": "Vigencia del elemento (vig_hasta 100 % vacío).", "vig_hasta": "Vigencia del elemento (vig_hasta 100 % vacío).", "geom": "Geometría PostGIS. Fuera del Excel (GeoJSON por capa).", "propiedades": "Atributos tematicos del elemento en JSON (jerarquia, sentido, siniestros, indices...); varian por capa."}, "capa_indicador": {"id_capa": "→ capa.id.", "id_indicador": "→ indicador.id.", "capa_archivo": "Columna de lectura (no se almacena en la base).", "indicador_clave": "Columna de lectura (no se almacena en la base)."}, "bitacora_cambio": {"id": "Identificador del evento.", "id_usuario": "→ usuario.id. Vacío en procesos automáticos (cargas, tareas programadas).", "tabla_afectada": "Tabla donde ocurrió el cambio.", "id_registro": "Llave del registro afectado (texto para admitir uuid, entero y alfanumérico).", "accion": "INSERT | UPDATE | DELETE | cambio de estado.", "datos_previos": "Fotografía antes del cambio.", "datos_nuevos": "Fotografía después del cambio.", "ip_origen": "IP de la petición.", "fecha": "Momento del evento."}, "evidencia_medicion": {"id": "Identificador de la evidencia.", "id_medicion": "→ medicion_indicador.id.", "id_usuario": "→ usuario.id que sube el archivo.", "url_archivo": "Ruta o URL del documento.", "tipo_documento": "Oficio, reporte, base de datos, fotografía….", "hash_archivo": "SHA-256 en hexadecimal (64 caracteres).", "fecha_subida": "Momento de la carga."}, "matriz_instrumento": {"id": "ID del instrumento + R + número de renglón (PimusCar01R07). No usa la clave OE porque se repite en algunas matrices.", "id_instrumento": "→ instrumento_origen.id.", "clave_oe": "Clave del objetivo específico tal como viene en el PIMUS (OE1, E3_OE_2…).", "objetivo": "Objetivo u objetivo específico.", "meta": "Meta del PIMUS.", "indicador_origen": "Indicador tal como lo nombra el PIMUS.", "tendencia": "Ascendente | Descendente | otra expresión del PIMUS (100 %, igual o menor a la inflación).", "indicadores_sesim": "Lectura: IM-xx equivalentes (no se almacena; sale de indicador_instrumento)."}, "indicador_instrumento": {"id": "Identificador del vínculo.", "id_indicador": "→ indicador.id.", "id_instrumento": "→ instrumento_origen.id.", "id_matriz": "→ matriz_instrumento.id. Vacío en los vínculos con la EEMSV (no hay matriz cargada).", "correspondencia": "origen (el indicador nace del instrumento) | directa (mide lo mismo) | parcial (mide un aspecto).", "indicador_clave": "Columnas de lectura (no se almacenan).", "clave_oe": "Columnas de lectura (no se almacenan)."}, "invitacion": {"id": "Identificador de la invitación.", "token_hash": "SHA-256 del token enviado.", "id_perfil": "→ perfil.id que tendrá la cuenta.", "correo_destino": "Correo institucional al que se envía.", "id_usuario_emisor": "→ usuario.id del Administrador Titular que la emite.", "expira_en": "Caducidad del token.", "usada_en": "Momento en que se usó.", "id_usuario_creado": "→ usuario.id creado con esta invitación.", "revocada": "TRUE si se canceló antes de usarse.", "created_at": "Emisión.", "rol": "Rol que tendra la cuenta invitada."}, "bitacora": {"id": "Identificador del evento de cuenta.", "actor_id_usuario": "Cuenta que hizo el cambio (nulo en procesos de sistema).", "actor_rol": "Rol de quien hizo el cambio al momento del evento.", "objetivo_id_usuario": "Cuenta afectada por el cambio.", "objetivo_rol": "Rol de la cuenta afectada al momento del evento (fotografia, no referencia viva).", "accion": "alta | cambio_rol | cambio_ambito | baja | reactivacion.", "detalle": "Datos del cambio en JSON (rol anterior y nuevo, etc.).", "creado_en": "Momento del evento."}, "perfil": {"id": "Identificador del perfil.", "id_usuario": "Cuenta de Supabase (auth.users.id) a la que pertenece; es el id de usuario del sistema.", "nombre": "Nombre completo de la persona.", "rol": "capturista | administrador | administrador_titular | auditor.", "ambito": "estatal | municipal. Hoy siempre estatal; el municipal es semilla latente.", "cve_mun": "Municipio de la cuenta si el ambito fuera municipal; hoy nulo.", "dependencia": "Area o dependencia institucional (catalogo pendiente).", "activo": "Baja logica: false = cuenta dada de baja (se conserva su historial).", "creado_en": "Fecha de alta."}, "schema_migraciones": {"nombre": "Archivo de migracion aplicado.", "sha256": "Huella del archivo al aplicarse; si cambia despues, el runner aborta.", "origen": "initdb | runner | adoptada.", "aplicada_en": "Momento de aplicacion."}, "capa_version": {"id": "Identificador de la version.", "id_capa": "Capa versionada.", "version": "Numero de version (1 = carga oficial inicial).", "estatus": "Estatus de la capa en esa version.", "metadatos": "Fotografia de los metadatos en esa version.", "id_usuario": "Quien genero la version (nulo en cargas de sistema).", "nota": "Motivo del cambio.", "created_at": "Momento de la version."}, "dictamen": {"id": "Identificador del dictamen.", "objeto_tipo": "medicion | capa | indicador.", "objeto_id": "Llave del objeto dictaminado, como texto.", "decision": "validar | rechazar | publicar.", "estado_previo": "Estado antes de la decision.", "estado_nuevo": "Estado despues de la decision.", "comentario": "Motivo; obligatorio al rechazar.", "id_usuario": "Administrador que dictamina.", "fecha": "Momento del dictamen."}, "hallazgo_auditoria": {"id": "Identificador del hallazgo.", "id_medicion": "Medicion observada.", "id_auditor": "Auditor que lo levanta.", "descripcion": "Que se observa.", "severidad": "baja | media | alta.", "estado": "abierto | atendido | cerrado.", "respuesta": "Respuesta de la administracion.", "fecha": "Momento del hallazgo.", "fecha_cierre": "Fecha de cierre; obligatoria si esta cerrado."}, "indicador_eje": {"id_indicador": "Indicador.", "id_eje": "Eje que atiende.", "principal": "true en el eje principal (uno por indicador, igual a indicador.id_eje)."}, "umbral_semaforo": {"id": "Identificador del umbral.", "id_indicador": "Indicador al que aplica; nulo = umbral global.", "verde_desde": "Porcentaje de cumplimiento desde el cual es verde (90).", "amarillo_desde": "Porcentaje desde el cual es amarillo (70); por debajo es rojo.", "vigente_desde": "Inicio de vigencia.", "vigente_hasta": "Fin de vigencia; nulo = vigente.", "id_usuario": "Quien lo definio.", "created_at": "Alta del registro."}}}$j$::jsonb;
  t text; c text; d text;
begin
  for t, d in select key, value from jsonb_each_text(j->'tablas') loop
    if to_regclass('core.' || t) is not null and obj_description(to_regclass('core.' || t), 'pg_class') is null then
      execute format('comment on table core.%I is %L', t, d);
    end if;
  end loop;
  for t in select key from jsonb_each(j->'campos') loop
    if to_regclass('core.' || t) is null then continue; end if;
    for c, d in select key, value from jsonb_each_text(j->'campos'->t) loop
      if exists (select 1 from pg_attribute a where a.attrelid = to_regclass('core.' || t) and a.attname = c
                    and a.attnum > 0 and not a.attisdropped)
         and col_description(to_regclass('core.' || t), (select attnum from pg_attribute where attrelid = to_regclass('core.' || t) and attname = c)) is null then
        execute format('comment on column core.%I.%I is %L', t, c, d);
      end if;
    end loop;
  end loop;
end $c$;
